// Makes a new array holding 1, 4, 9, ..., n * n and stores its address
// in *out. Returns 0 on success, or -1 (and leaves *out alone) on failure.
int make_squares(size_t n, int **out) {
    if (n == 0) {
        return -1;
    }
    int *sq = malloc(n * sizeof(int));
    if (!sq) {
        return -1;
    }
    for (size_t i = 0; i < n; i++) {
        sq[i] = (int) ((i + 1) * (i + 1));
    }
    *out = sq;               // give the caller the new array
    return 0;
}

