#include <stdio.h>
#include <stdlib.h>

// Makes a new array holding the positive values of a[0..n-1], in order, and
// stores its address in *out. Returns how many values it holds. If there are
// none, or malloc fails, sets *out to NULL and returns 0. The caller must free *out.
size_t copy_positive(const int a[], size_t n, int **out) {
    *out = NULL;
    size_t count = 0;
    for (size_t i = 0; i < n; i++) {        // pass 1: how many?
        if (a[i] > 0) {
            count++;
        }
    }
    if (count == 0) {
        return 0;
    }
    int *pos = malloc(count * sizeof(int)); // exactly the right size
    if (!pos) {
        return 0;
    }
    size_t k = 0;
    for (size_t i = 0; i < n; i++) {        // pass 2: copy them
        if (a[i] > 0) {
            pos[k] = a[i];
            k++;
        }
    }
    *out = pos;                             // set the caller's pointer
    return count;
}

int main(void) {
    int data[] = {3, -1, 0, 8, -5, 2};
    int *p;
    size_t m = copy_positive(data, 6, &p);
    for (size_t i = 0; i < m; i++) {
        printf("%d ", p[i]);
    }
    printf("(%zu values)\n", m);
    free(p);                                // free(NULL) is fine if m == 0
    return 0;
}

