#include <stdio.h>
#include <stdlib.h>

// Appends value to the heap array *arr, which holds *n values and has room
// for *cap. If it is full, first doubles the capacity with realloc.
// Returns 0 on success, -1 if realloc fails (the array is then unchanged).
int push(int **arr, size_t *n, size_t *cap, int value) {
    if (*n == *cap) {
        int *tmp = realloc(*arr, 2 * *cap * sizeof(int));
        if (!tmp) {
            return -1;
        }
        *arr = tmp;
        *cap = 2 * *cap;
    }
    (*arr)[*n] = value;
    *n = *n + 1;
    return 0;
}

int main(void) {
    size_t n = 0;
    size_t cap = 1;
    int *a = malloc(cap * sizeof(int));
    if (!a) {
        return 1;
    }
    for (int v = 1; v <= 5; v++) {
        if (push(&a, &n, &cap, v * v) != 0) {
            free(a);
            return 1;
        }
    }
    for (size_t i = 0; i < n; i++) {
        printf("%d ", a[i]);
    }
    printf("\nn = %zu, cap = %zu\n", n, cap);
    free(a);
    a = NULL;
    return 0;
}

write.prompt:
Write a `main` (with the `#include`s it needs) that shows how to:

(a) use `malloc` to allocate memory for an array of 4 strings where each string can hold 12 characters (hint: five calls to `malloc`);

(b) store the strings "pointer", "heap", "struct" and "realloc" in them;

(c) use `realloc` so that the third string can **safely** store a null-terminated string of 30 characters, then append "s on the heap" to it and print all four strings;

(d) release all of the memory.

Check every allocation for failure (free what you already have, print a message to standard error and exit with `EXIT_FAILURE`).

write.solution:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int main(void) {
    // (a) an array of 4 strings, each able to hold 12 characters
    char **names = malloc(4 * sizeof(char *));      // 1 call for the array
    if (!names) {
        fprintf(stderr, "out of memory\n");
        exit(EXIT_FAILURE);
    }
    for (int i = 0; i < 4; i++) {
        names[i] = malloc(12 + 1);                  // 4 calls: 12 chars + '\0'
        if (!names[i]) {
            for (int j = 0; j < i; j++) {
                free(names[j]);
            }
            free(names);
            fprintf(stderr, "out of memory\n");
            exit(EXIT_FAILURE);
        }
    }

    // (b) store the four strings
    strcpy(names[0], "pointer");
    strcpy(names[1], "heap");
    strcpy(names[2], "struct");
    strcpy(names[3], "realloc");

    // (c) make names[2] big enough for 30 characters, safely
    char *tmp = realloc(names[2], 30 + 1);
    if (!tmp) {
        for (int i = 0; i < 4; i++) {
            free(names[i]);                         // names[2] is still valid
        }
        free(names);
        fprintf(stderr, "out of memory\n");
        exit(EXIT_FAILURE);
    }
    names[2] = tmp;
    strcat(names[2], "s on the heap");              // now 19 characters

    for (int i = 0; i < 4; i++) {
        printf("%s\n", names[i]);
    }

    // (d) release everything: the strings first, then the array
    for (int i = 0; i < 4; i++) {
        free(names[i]);
    }
    free(names);
    return 0;
}
